import { clamp } from './util.js';

export const SPEED = 2;
export const MAX_HP = 100;

export function move(p, dx, dy) {
  p.x += dx * SPEED;
  p.y += dy * SPEED;
  return p;
}

export function heal(p, amount) {
  p.hp = p.hp + amount;
  return p;
}

export function damage(p, amount) {
  p.hp = clamp(p.hp - amount, 0, MAX_HP);
  return p.hp === 0;
}

export function describe(p) {
  return `Player at ${p.x},${p.y} with ${p.hp} HP`;
}
